import{_ as i,a0 as m,w as p,s as l,I as o,x as n,a1 as r,A as s,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux中命令链接操作符的十个最佳实例 | LCTT x X-CMD","titleTemplate":false,"description":"Linux中命令链接操作符的十个最佳实例 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux中命令链接操作符的十个最佳实例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux中命令链接操作符的十个最佳实例 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/10 Useful Chaining Operators in Linux with Practical Examples","title":"Linux中命令链接操作符的十个最佳实例","tag":"201401","desc":""},"relativePath":"201401/10 Useful Chaining Operators in Linux with Practical Examples.md","filePath":"[post].md"}'),d={name:"201401/10 Useful Chaining Operators in Linux with Practical Examples.md"};function g(c,t,h,x,u,w){const e=m("Link");return p(),l("div",null,[t[26]||(t[26]=o("h1",{id:"linux中命令链接操作符的十个最佳实例",tabindex:"-1"},[n("Linux中命令链接操作符的十个最佳实例 "),o("a",{class:"header-anchor",href:"#linux中命令链接操作符的十个最佳实例","aria-label":"Permalink to “Linux中命令链接操作符的十个最佳实例”"},"​")],-1)),o("p",null,[t[1]||(t[1]=n("Linux命令中的链接的意思是，通过操作符的行为将几个命令组合执行。Linux中的链接命令，有些像你在shell中写",-1)),r(e,{href:"http://www.tecmint.com/category/bash-shell/"},{default:s(()=>[...t[0]||(t[0]=[n("短小的shell脚本",-1)])]),_:1}),t[2]||(t[2]=n("，并直接在终端中执行。链接使得自动处理变得更方便。不仅如此，一个无人看管的机器在链接操作符的帮助下能够十分有条理地运行。",-1))]),t[27]||(t[27]=a(`<p><img src="http://www.tecmint.com/wp-content/uploads/2013/12/Chaining-Operators-in-Linux.png" alt="Linux中的10个链接操作符"></p><p><em>Linux中的10个链接操作符</em></p><p>本文旨在介绍一些常用的<strong>链接操作符</strong>，通过简短的描述和相关的例子帮助读者提高生产力、降低系统负载、写出更加简短有意义的代码。</p><h3 id="_1-和号操作符" tabindex="-1">1. 和号操作符 (&amp;) <a class="header-anchor" href="#_1-和号操作符" aria-label="Permalink to “1. 和号操作符 (&amp;)”">​</a></h3><p>‘<strong>&amp;</strong>’的作用是使命令在后台运行。只要在命令后面跟上一个空格和 ‘<strong>&amp;</strong>’。你可以一口气在后台运行多个命令。</p><p>在后台运行一个命令:</p><pre><code>tecmint@localhost:~$ ping ­c5 www.tecmint.com &amp;
</code></pre><p>同时在后台运行两个命令：</p><pre><code>root@localhost:/home/tecmint# apt-get update &amp; mkdit test &amp;
</code></pre><h3 id="_2-分号操作符" tabindex="-1">2. 分号操作符 (😉 <a class="header-anchor" href="#_2-分号操作符" aria-label="Permalink to “2. 分号操作符 (”">​</a></h3><p>分号操作符使你可以一口气运行几个命令，命令顺序执行。</p><pre><code>root@localhost:/home/tecmint# apt-get update ; apt-get upgrade ; mkdir test
</code></pre><p>上述命令先后执行了update和upgrade，最后在当前工作目录下创建了一个‘<strong>test</strong>’文件夹</p><h3 id="_3-与操作符" tabindex="-1">3. 与操作符 (&amp;&amp;) <a class="header-anchor" href="#_3-与操作符" aria-label="Permalink to “3. 与操作符 (&amp;&amp;)”">​</a></h3><p>如果第一个命令执行成功，<strong>与操作符 (&amp;&amp;)</strong>才会执行第二个命令，也就是说，第一个命令退出状态是<strong>0</strong>。（译注：原文的这里明显写错了，我们进行了改译，有兴趣的读者可以参看原文以及原文下面的评论。在UNIX里面，0表示无错误，而所有非0返回值都是各种错误）。这个命令在检查最后一个命令的执行状态时很有用。</p>`,15)),o("p",null,[t[4]||(t[4]=n("比如，我想使用",-1)),o("strong",null,[r(e,{href:"http://www.tecmint.com/command-line-web-browsers/"},{default:s(()=>[...t[3]||(t[3]=[n("links 命令",-1)])]),_:1})]),t[5]||(t[5]=n("在终端中访问网站",-1)),t[6]||(t[6]=o("strong",null,"tecmint.com",-1)),t[7]||(t[7]=n("，但在这之前我需要检查主机是否",-1)),t[8]||(t[8]=o("strong",null,"在线",-1)),t[9]||(t[9]=n("或",-1)),t[10]||(t[10]=o("strong",null,"不在线",-1)),t[11]||(t[11]=n("。",-1))]),t[28]||(t[28]=a(`<pre><code>root@localhost:/home/tecmint# ping -c3 www.tecmint.com &amp;&amp; links www.tecmint.com
</code></pre><h3 id="_4-或操作符" tabindex="-1">4. 或操作符 (||) <a class="header-anchor" href="#_4-或操作符" aria-label="Permalink to “4. 或操作符 (||)”">​</a></h3><p><strong>或操作符 (||)</strong>很像编程中的<strong>else</strong>语句。上面的操作符允许你在第一个命令失败的情况下执行第二个命令，比如，第一个命令的退出状态是<strong>1</strong>。</p><p>举例来说，我想要在非root帐户中执行‘<strong>apt-get update</strong>‘，如果第一个命令失败了，接着会执行第二个命令‘<strong>links www.tecmint.com</strong>‘。</p><pre><code>tecmint@localhost:~$ apt-get update || links tecmint.com
</code></pre><p>上面的命令中，由于该<strong>用户</strong>不允许<strong>更新</strong>系统，这意味着第一个命令的退出状态是’<strong>1</strong>′,因此最后一个命令‘<strong>links tecmint.com</strong>‘会执行。</p><p>如果第一个命令成功执行并且退出状态是‘<strong>0</strong>‘呢？很明显的，第二个命令不会执行。</p><pre><code>tecmint@localhost:~$ mkdir test || links tecmint.com
</code></pre><p>这里，用户在家目录创建了一个‘<strong>test</strong>‘文件夹，这是被允许的。命令成功的执行，退出状态是‘<strong>0</strong>‘,因此，最后的命令不会执行。</p><h3 id="_5-非操作符" tabindex="-1">5. 非操作符 (!) <a class="header-anchor" href="#_5-非操作符" aria-label="Permalink to “5. 非操作符 (!)”">​</a></h3><p><strong>非操作符 (!)</strong>很像<strong>except</strong>语句。这个命令会执行除了提供的条件外的所有的语句。要理解这点，在你的主目录创建一个目录‘<strong>tecmint</strong>’，并‘<strong>cd</strong>’到它这里。</p><pre><code>tecmint@localhost:~$ mkdir tecmint 
tecmint@localhost:~$ cd tecmint
</code></pre><p>接下来，在文件夹‘<strong>tecmint</strong>’下创建不同类型的文件。</p><pre><code>tecmint@localhost:~/tecmint$ touch a.doc b.doc a.pdf b.pdf a.xml b.xml a.html b.html
</code></pre><p>看一下我们在文件夹‘<strong>tecmint</strong>’创建的新文件。</p><pre><code>tecmint@localhost:~/tecmint$ ls 

a.doc  a.html  a.pdf  a.xml  b.doc  b.html  b.pdf  b.xml
</code></pre><p>用一种聪明的办法马上删除除了 ‘<strong>html</strong>’之外的所有文件。</p><pre><code>tecmint@localhost:~/tecmint$ rm -r !(*.html)
</code></pre>`,18)),o("p",null,[t[13]||(t[13]=n("验证一下上次的执行结果，使用",-1)),r(e,{href:"http://www.tecmint.com/15-basic-ls-command-examples-in-linux/"},{default:s(()=>[...t[12]||(t[12]=[n("ls 命令",-1)])]),_:1}),t[14]||(t[14]=n("列出可见所有文件。",-1))]),t[29]||(t[29]=a(`<pre><code>tecmint@localhost:~/tecmint$ ls 

a.html  b.html
</code></pre><h3 id="_6-与或操作符-–" tabindex="-1">6. 与或操作符 (&amp;&amp; – ||) <a class="header-anchor" href="#_6-与或操作符-–" aria-label="Permalink to “6. 与或操作符 (&amp;&amp; – ||)”">​</a></h3><p>上面的操作符实际上是‘<strong>与</strong>’和‘<strong>或</strong>’操作符的组合。它很像‘<strong>if-else</strong>‘语句。</p><p>比如，我们ping <strong>tecmint.com</strong>，如果成功打印‘<strong>已验证</strong>’，否则打印‘<strong>主机故障</strong>’。</p><pre><code>tecmint@localhost:~/tecmint$ ping -c3 www.tecmint.com &amp;&amp; echo &quot;Verified&quot; || echo &quot;Host Down&quot;
</code></pre><h4 id="示例输出" tabindex="-1">示例输出 <a class="header-anchor" href="#示例输出" aria-label="Permalink to “示例输出”">​</a></h4><pre><code>PING www.tecmint.com (212.71.234.61) 56(84) bytes of data. 
64 bytes from www.tecmint.com (212.71.234.61): icmp_req=1 ttl=55 time=216 ms 
64 bytes from www.tecmint.com (212.71.234.61): icmp_req=2 ttl=55 time=224 ms 
64 bytes from www.tecmint.com (212.71.234.61): icmp_req=3 ttl=55 time=226 ms 

--- www.tecmint.com ping statistics --- 
3 packets transmitted, 3 received, 0% packet loss, time 2001ms 
rtt min/avg/max/mdev = 216.960/222.789/226.423/4.199 ms 
Verified
</code></pre><p>现在，断开我们现在的网络连接诶，再试一下相同的命令。</p><pre><code>tecmint@localhost:~/tecmint$ ping -c3 www.tecmint.com &amp;&amp; echo &quot;verified&quot; || echo &quot;Host Down&quot;
</code></pre><h4 id="实例输出" tabindex="-1">实例输出 <a class="header-anchor" href="#实例输出" aria-label="Permalink to “实例输出”">​</a></h4><pre><code>ping: unknown host www.tecmint.com 
Host Down
</code></pre><h3 id="_7-管道操作符" tabindex="-1">7. 管道操作符 (|) <a class="header-anchor" href="#_7-管道操作符" aria-label="Permalink to “7. 管道操作符 (|)”">​</a></h3><p><strong>PIPE</strong>在将第一个命令的输出作为第二个命令的输入时很有用。比如，‘<strong>ls -l</strong>’的输出通过管道到‘<strong>less</strong>’，并看一下输出。</p><pre><code>tecmint@localhost:~$ ls -l | less
</code></pre><h3 id="_8-命令合并操作符" tabindex="-1">8. 命令合并操作符 {} <a class="header-anchor" href="#_8-命令合并操作符" aria-label="Permalink to “8. 命令合并操作符 {}”">​</a></h3><p>合并两个或多个命令，第二个命令依赖于第一个命令的执行。</p><p>比如，检查一下文件‘<strong>xyz.txt</strong>’是否在<strong>Downloads</strong>目录下，如果不存在则创建之并输出提示信息。</p><pre><code>tecmint@localhost:~$ [ -f /home/tecmint/Downloads/xyz.txt ] || touch /home/tecmint/Downloads/xyz.txt; echo &quot;The file does not exist&quot;
</code></pre><p>但是这样的命令的运行结果并不如我们预期的运行，会始终都输出提示信息。因此需要使用{}操作符来合并命令：</p><pre><code>tecmint@localhost:~$ [ -f /home/tecmint/Downloads/xyz1.txt ] || {touch /home/tecmint/Downloads/xyz.txt; echo &quot;The file does not exist&quot;}

“The file does not exist”
</code></pre><p>（译注：原文这里应该也是复制或书写的时候，出现了一些问题，例子中并没有出现小标题中的&quot;{}&quot;操作符，所以这里我们进行了修改）</p><h3 id="_9-优先操作符" tabindex="-1">9. 优先操作符 () <a class="header-anchor" href="#_9-优先操作符" aria-label="Permalink to “9. 优先操作符 ()”">​</a></h3><p>这个操作符可以让命令以优先顺序执行。</p><pre><code>Command_x1 &amp;&amp;Command_x2 || Command_x3 &amp;&amp; Command_x4.
</code></pre><p>在上面的伪代码中，如果<strong>Command_x1</strong>执行失败了会怎么样，<strong>Command_x2</strong>, <strong>Command_x3</strong>, <strong>Command_x4</strong>没有一个会执行，对于这种情况，我们使用<strong>优先操作符</strong>。</p><pre><code>(Command_x1 &amp;&amp;Command_x2) || (Command_x3 &amp;&amp; Command_x4)
</code></pre><p>在上面的伪代码中，如果<strong>Command_x1</strong>执行失败，<strong>Command_x2</strong>不会执行，但是<strong>Command_x3</strong>会继续执行， <strong>Command_x4</strong>会依赖于 <strong>Command_x3</strong>的退出状态。</p><h3 id="_10-连接符" tabindex="-1">10. 连接符 () <a class="header-anchor" href="#_10-连接符" aria-label="Permalink to “10. 连接符 ()”">​</a></h3><p><strong>连接符 ()</strong>如它名字所说，被用于连接shell中那些太长而需要分成多行的命令。可以在输入一个“\\”之后就回车，然后继续输入命令行，直到输入完成。比如，下面的命令会打开文本文件<strong>test(1).txt</strong>。</p><pre><code>tecmint@localhost:~/Downloads$ nano test\\
1.txt
</code></pre><p>今天就到这里，我会近日开始另外一个有趣的文章。不要走开，继续关注<strong>Tecmint</strong>。不要忘记在评论栏里提出有价值的反馈。</p><hr>`,32)),o("p",null,[t[16]||(t[16]=n("via: ",-1)),r(e,{href:"http://www.tecmint.com/chaining-operators-in-linux-with-practical-examples/"},{default:s(()=>[...t[15]||(t[15]=[n("http://www.tecmint.com/chaining-operators-in-linux-with-practical-examples/",-1)])]),_:1})]),o("p",null,[t[19]||(t[19]=n("译者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:s(()=>[...t[17]||(t[17]=[n("geekpi",-1)])]),_:1}),t[20]||(t[20]=n(" 校对：",-1)),r(e,{href:"http://blog.csdn.net/tinyeyeser"},{default:s(()=>[...t[18]||(t[18]=[n("Mr小眼儿",-1)])]),_:1})]),o("p",null,[t[23]||(t[23]=n("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[21]||(t[21]=[n("LCTT",-1)])]),_:1}),t[24]||(t[24]=n(" 原创翻译，",-1)),r(e,{href:"http://linux.cn/"},{default:s(()=>[...t[22]||(t[22]=[n("Linux中国",-1)])]),_:1}),t[25]||(t[25]=n(" 荣誉推出",-1))])])}const C=i(d,[["render",g]]);export{_ as __pageData,C as default};
